/// <summary>
/// designed from AVA
/// </summary>
/// <param name="args">args</param>
[PostHandlerFor(formStr(LogisticsAddressZipCodeLookup), formMethodStr(LogisticsAddressZipCodeLookup, init))]
public static void LogisticsAddressZipCodeLookup_Post_init(XppPrePostArgs args)
{
    FormRun                 formRun = args.getThis();
    FormDataSource          zipCodeDS = formRun.dataSource('ZipCode');
    FormRun                 callerFormRun;

    if (formRun.args().caller() is FormControl)
    {
        FormControl         callerControl = formRun.args().caller();
        callerFormRun = callerControl.formRun();
        FormDataSource  buildingProjectDS = callerFormRun.dataSource('KCS_KBVBuildingProjectTable');
        if (buildingProjectDS)
        {
            KCS_KBVBuildingProjectTable     buildingProject = buildingProjectDS.cursor();
            if (zipCodeDS)
            {
                zipCodeDS.query().dataSourceTable(tableNum(LogisticsAddressZipCode)).addRange(fieldNum(LogisticsAddressZipCode,City)).value(buildingProject.AddressCity);
                zipCodeDS.query().dataSourceTable(tableNum(LogisticsAddressZipCode)).addRange(fieldNum(LogisticsAddressZipCode, CountryRegionId)).value(buildingProject.AddressCountryRegionId);
            }
        }
    }

    FormStringControl  streetNameCtrl =  formRun.design().controlName('Grid_StreetName');
    if (StreetNameCtrl)
    {
        streetNameCtrl.displayHeight(1,AutoMode::Fixed);
    }
}
